     },
     {
         id: 'q3',
         title: 'Which of these are compiled languages?',
         options: [
             { id: 'c', label: 'C' },
             { id: 'rust', label: 'Rust' },
             { id: 'go', label: 'Go' },
             { id: 'ruby', label: 'Ruby' }
         ],
         correct: ['c', 'rust', 'go']
     }
 ];

 function CheckboxGroup({ question, index, onToggle }) {
     const helpId = `${question.id}-help`;

     return `
         <div class="form-field">
             <fieldset ${question.helpText ? `aria-describedby="${helpId}"` : ''}>
                 <legend>${index + 1}. ${question.title}</legend>
                 ${question.helpText ? `<span id="${helpId}" class="help-text">${question.helpText}</span>` : ''}

                 ${question.options.map(option => {
                     const optionId = `${question.id}-${option.id}`;
                     return `
                         <div class="checkbox-item">
                             <input 
                                 type="checkbox" 
                                 id="${optionId}" 
                                 name="${question.id}" 
                                 value="${option.id}"
                                 data-qindex="${index}"
                             >
                             <label for="${optionId}">${option.label}</label>
                         </div>
                     `;
                 }).join('')}
             </fieldset>
         </div>
     `;
 }

 class QuizApp {
     constructor(questions) {
         this.questions = questions;
         this.userAnswers = questions.map(() => []);
         this.submitted = false;
         this.root = document.getElementById('root');

         this.init();
     }

     init() {
         this.render();
     }

     handleToggle(qIndex, optionId) {
         const currentAnswers = this.userAnswers[qIndex];
         if (currentAnswers.includes(optionId)) {
             this.userAnswers[qIndex] = currentAnswers.filter(id => id !== optionId);
         } else {
             this.userAnswers[qIndex] = [...currentAnswers, optionId];
         }
     }

     handleSubmit(e) {
         e.preventDefault();
         this.submitted = true;
         this.render();
         // Move focus to results header for accessibility
         const resultsHeader = document.querySelector('.results h2');
         if (resultsHeader) {
             resultsHeader.setAttribute('tabindex', '-1');
             resultsHeader.focus();
         }
     }

     calculateScore() {
         let correctCount = 0;
         this.userAnswers.forEach((answers, i) => {
             const correct = this.questions[i].correct;
             const isCorrect = answers.length === correct.length && 
                               answers.every(a => correct.includes(a));
             if (isCorrect) correctCount++;
         });
         return correctCount;
     }

     render() {
         if (this.submitted) {
             const score = this.calculateScore();
             this.root.innerHTML = `
                 <main>
                     <header>
                         <h1>Quiz Results</h1>
                     </header>
                     <div class="results">
                         <h2>You scored ${score} out of ${this.questions.length}!</h2>
                         <p>Thank you for taking the Computer Languages Quiz.</p>
                         <button onclick="location.reload()">Try Again</button>
                     </div>
                 </main>
             `;
             return;
         }

         this.root.innerHTML = `
             <main>
                 <header>
                     <h1>Computer Languages Quiz</h1>
                     <p>Test your knowledge of programming languages.</p>
                 </header>
                 <form id="quiz-form">
                     ${this.questions.map((q, i) => CheckboxGroup({ question: q, index: i })).join('')}
                     <button type="submit">Submit Quiz</button>
                 </form>
             </main>
         `;

         const form = document.getElementById('quiz-form');
         form.addEventListener('submit', (e) => this.handleSubmit(e));

         form.querySelectorAll('input[type="checkbox"]').forEach(checkbox => {
             checkbox.addEventListener('change', (e) => {
                 const qIndex = parseInt(e.target.dataset.qindex);
                 const optionId = e.target.value;
                 this.handleToggle(qIndex, optionId);
             });

             // Restore state if re-rendering (though we don't re-render on toggle here for simplicity)
             const qIndex = parseInt(checkbox.dataset.qindex);
             if (this.userAnswers[qIndex].includes(checkbox.value)) {
                 checkbox.checked = true;
             }
         });
     }
 }

 new QuizApp(QUESTIONS);

