 const { chromium } = require('playwright');
 const fs = require('fs');
 const path = require('path');

 (async () => {
     let browser;
     try {
         browser = await chromium.launch();
     } catch (e) {
         console.error("Chromium launch failed, trying install...");
         const { execSync } = require('child_process');
         execSync('npx playwright install chromium >/dev/null 2>&1');
         browser = await chromium.launch();
     }
     const context = await browser.newContext();
     const page = await context.newPage();

     // Read the files and inject them to simulate the full page
     const html = fs.readFileSync('index.html', 'utf8');
     const css = fs.readFileSync('style.css', 'utf8');
     const js = fs.readFileSync('script.js', 'utf8');

     await page.setContent(html);
     await page.addStyleTag({ content: css });
     await page.addScriptTag({ content: js });

     // Wait for JS to render the quiz
     await page.waitForSelector('#quiz-form', { timeout: 5000 });

     const axeSource = fs.readFileSync('/tmp/axe.min.js', 'utf8');
     await page.addScriptTag({ content: axeSource });

     const results = await page.evaluate(async () => {
